 public class Palette {
  public string Background,Card,Ink,Muted,Line,Gold,Soft,Border,Female;
  public static Palette Get(int theme){if(theme==1)return new Palette{Background="#112629",Card="#1d3639",Ink="#f5f0df",Muted="#a9c1bb",Line="#5e8e83",Gold="#dec38b",Soft="#173034",Border="#36514f",Female="#daa5a1"};if(theme==2)return new Palette{Background="#ffffff",Card="#ffffff",Ink="#111111",Muted="#555555",Line="#444444",Gold="#666666",Soft="#f7f7f7",Border="#bbbbbb",Female="#666666"};return new Palette{Background="#f6f4ed",Card="#fffefa",Ink="#203f37",Muted="#7c897e",Line="#88a393",Gold="#b48a49",Soft="#eeeee4",Border="#d8dfd3",Female="#b67c79"};}
 }
 public sealed class DiagramCanvas {
  Graphics g;StringBuilder svg;public string FontName="Microsoft YaHei UI";
  public DiagramCanvas(Graphics graphics){g=graphics;if(g!=null){g.SmoothingMode=SmoothingMode.AntiAlias;g.TextRenderingHint=System.Drawing.Text.TextRenderingHint.AntiAliasGridFit;}}
  public DiagramCanvas(float width,float height){svg=new StringBuilder("<?xml version='1.0' encoding='UTF-8'?>\n<svg xmlns='http://www.w3.org/2000/svg' xmlns:xlink='http://www.w3.org/1999/xlink' width='"+N(width)+"' height='"+N(height)+"' viewBox='0 0 "+N(width)+" "+N(height)+"' role='img'><title>"+Store.X(Store.Data.Title)+" · 景·谱世系图</title><desc>矢量世系图；实线为亲子，虚线为配偶。照片如启用则内嵌位图。</desc>");}
  public static string N(float v){return v.ToString("0.##",CultureInfo.InvariantCulture);}
  static Color ColorOf(string s){return ColorTranslator.FromHtml(s);}
  public static GraphicsPath Rounded(RectangleF r,float radius){float d=Math.Min(radius*2,Math.Min(r.Width,r.Height));var p=new GraphicsPath();p.AddArc(r.X,r.Y,d,d,180,90);p.AddArc(r.Right-d,r.Y,d,d,270,90);p.AddArc(r.Right-d,r.Bottom-d,d,d,0,90);p.AddArc(r.X,r.Bottom-d,d,d,90,90);p.CloseFigure();return p;}
  public void Rect(float x,float y,float w,float h,string fill,float radius=0,string stroke=null,float weight=1){if(g!=null){using(var b=new SolidBrush(ColorOf(fill))){if(radius>0){using(var p=Rounded(new RectangleF(x,y,w,h),radius))g.FillPath(b,p);}else g.FillRectangle(b,x,y,w,h);}if(stroke!=null)using(var pen=new Pen(ColorOf(stroke),weight)){if(radius>0){using(var p=Rounded(new RectangleF(x,y,w,h),radius))g.DrawPath(pen,p);}else g.DrawRectangle(pen,x,y,w,h);}}if(svg!=null)svg.Append("<rect x='"+N(x)+"' y='"+N(y)+"' width='"+N(w)+"' height='"+N(h)+"' rx='"+N(radius)+"' fill='"+fill+"'"+(stroke==null?"":" stroke='"+stroke+"' stroke-width='"+N(weight)+"'")+"/>");}
  public void Circle(float x,float y,float r,string fill,string stroke=null){if(g!=null){using(var b=new SolidBrush(ColorOf(fill)))g.FillEllipse(b,x-r,y-r,r*2,r*2);if(stroke!=null)using(var p=new Pen(ColorOf(stroke),1.4f))g.DrawEllipse(p,x-r,y-r,r*2,r*2);}if(svg!=null)svg.Append("<circle cx='"+N(x)+"' cy='"+N(y)+"' r='"+N(r)+"' fill='"+fill+"'"+(stroke==null?"":" stroke='"+stroke+"' stroke-width='1.4'")+"/>");}
  public void Line(IEnumerable<PointF> points,string color,float width=1.6f,bool dash=false){var pts=points.ToArray();if(pts.Length<2)return;if(g!=null)using(var pen=new Pen(ColorOf(color),width)){pen.LineJoin=LineJoin.Round;pen.StartCap=pen.EndCap=LineCap.Round;if(dash)pen.DashPattern=new[]{4f,3f};g.DrawLines(pen,pts);}if(svg!=null)svg.Append("<polyline fill='none' stroke='"+color+"' stroke-width='"+N(width)+"' stroke-linecap='round' stroke-linejoin='round'"+(dash?" stroke-dasharray='5 4'":"")+" points='"+String.Join(" ",pts.Select(p=>N(p.X)+","+N(p.Y)))+"'/>");}
  public void Segment(float x,float y,float xx,float yy,string c,float w=1.6f,bool dash=false){Line(new[]{new PointF(x,y),new PointF(xx,yy)},c,w,dash);}
  public static string Fit(string text,float width,float size){if(String.IsNullOrEmpty(text))return "";float used=0;var b=new StringBuilder();foreach(char ch in text.Replace('\r',' ').Replace('\n',' ')){used+=size*(ch<128?.54f:1f);if(used>width-size)return b.ToString()+"…";b.Append(ch);}return b.ToString();}
  public void Text(string text,float x,float y,float size,string color,bool bold=false,float maxWidth=10000){text=Fit(text,maxWidth,size);if(g!=null)using(var font=new Font(FontName,size,bold?FontStyle.Bold:FontStyle.Regular,GraphicsUnit.Pixel))using(var b=new SolidBrush(ColorOf(color)))using(var format=new StringFormat(StringFormat.GenericTypographic)){format.FormatFlags=StringFormatFlags.NoWrap;g.DrawString(text,font,b,new PointF(x,y),format);}if(svg!=null)svg.Append("<text x='"+N(x)+"' y='"+N(y+size*.87f)+"' font-family='"+Store.X(FontName)+", Microsoft YaHei, sans-serif' font-size='"+N(size)+"' fill='"+color+"'"+(bold?" font-weight='700'":"")+">"+Store.X(text)+"</text>");}
  public bool Photo(string file,float x,float y,float size,string key){try{if(!File.Exists(file))return false;using(var original=Image.FromFile(file))using(var b=new Bitmap(128,128)){using(var crop=Graphics.FromImage(b)){crop.InterpolationMode=InterpolationMode.HighQualityBicubic;float side=Math.Min(original.Width,original.Height);crop.DrawImage(original,new RectangleF(0,0,128,128),new RectangleF((original.Width-side)/2,(original.Height-side)/2,side,side),GraphicsUnit.Pixel);}if(g!=null){var state=g.Save();using(var p=new GraphicsPath()){p.AddEllipse(x,y,size,size);g.SetClip(p);g.DrawImage(b,x,y,size,size);}g.Restore(state);}if(svg!=null){using(var m=new MemoryStream()){b.Save(m,ImageFormat.Png);svg.Append("<defs><clipPath id='photo"+key+"'><circle cx='"+N(x+size/2)+"' cy='"+N(y+size/2)+"' r='"+N(size/2)+"'/></clipPath></defs><image x='"+N(x)+"' y='"+N(y)+"' width='"+N(size)+"' height='"+N(size)+"' clip-path='url(#photo"+key+")' xlink:href='data:image/png;base64,"+Convert.ToBase64String(m.ToArray())+"'/>");}}}return true;}catch{return false;}}
  public string Svg(){return svg.ToString()+"</svg>";}
  public void BeginMember(string id,string name,string description){if(svg!=null)svg.Append("<g id='member-"+Store.X(id)+"' data-person='"+Store.X(name)+"'><title>"+Store.X(description)+"</title>");}
  public void EndMember(){if(svg!=null)svg.Append("</g>");}
  public void Brand(float x,float y,float size){if(g!=null){var state=g.Save();g.TranslateTransform(x,y);g.ScaleTransform(size/256f,size/256f);BrandMark.Draw(g);g.Restore(state);}if(svg!=null){string body=BrandMark.Svg.Substring(BrandMark.Svg.IndexOf('>')+1);body=body.Substring(0,body.LastIndexOf("</svg>",StringComparison.Ordinal));svg.Append("<g aria-label='景·谱 Logo' transform='translate("+N(x)+" "+N(y)+") scale("+N(size/256f)+")'>"+body+"</g>");}}
 }
 public class DiagramUnit {public int Index,Rank;public List<Person> Members=new List<Person>();public List<DiagramUnit> Children=new List<DiagramUnit>();public DiagramUnit Parent;public float Width,Subtree,X;}
 public class LineageLayout {
  public List<Person> People=new List<Person>();public Dictionary<string,RectangleF> Boxes=new Dictionary<string,RectangleF>();public Dictionary<string,int> Ranks=new Dictionary<string,int>();public List<DiagramUnit> Units=new List<DiagramUnit>();public SizeF Size;public int Layers;public float CardWidth,CardHeight;public string Notice="";
  public void Build(List<Person> people,DiagramOptions options){People=people;Boxes.Clear();Ranks.Clear();Units.Clear();Notice="";CardWidth=options.Compact?224:264;CardHeight=options.Compact?108:174;if(people.Count==0){Size=new SizeF(1000,580);Layers=0;return;}var byId=people.ToDictionary(p=>p.Id);var parent=people.ToDictionary(p=>p.Id,p=>p.Id);Func<string,string> root=null;root=id=>{while(parent[id]!=id){parent[id]=parent[parent[id]];id=parent[id];}return id;};Action<string,string> union=(a,b)=>{if(byId.ContainsKey(a)&&byId.ContainsKey(b)){string aa=root(a),bb=root(b);if(aa!=bb)parent[bb]=aa;}};
   foreach(var p in people){foreach(string spouse in p.Spouses)union(p.Id,spouse);if(byId.ContainsKey(p.FatherId)&&byId.ContainsKey(p.MotherId))union(p.FatherId,p.MotherId);}if(!CreateUnits(people,parent,root)){parent=people.ToDictionary(p=>p.Id,p=>p.Id);root=id=>id;CreateUnits(people,parent,root);Notice="复杂交叉亲缘已使用独立分层；部分配偶跨层显示。";}
   foreach(var unit in Units){unit.Width=unit.Members.Count*CardWidth+Math.Max(0,unit.Members.Count-1)*34;foreach(var p in unit.Members)Ranks[p.Id]=unit.Rank;}
   var memberUnit=new Dictionary<string,DiagramUnit>();foreach(var unit in Units)foreach(var p in unit.Members)memberUnit[p.Id]=unit;foreach(var unit in Units){var parents=unit.Members.SelectMany(p=>new[]{p.FatherId,p.MotherId}).Where(id=>memberUnit.ContainsKey(id)).Select(id=>memberUnit[id]).Where(u=>u!=unit&&u.Rank<unit.Rank).Distinct().OrderByDescending(u=>u.Rank).ThenBy(u=>u.Index).ToList();if(parents.Count>0){unit.Parent=parents[0];unit.Parent.Children.Add(unit);}}
   foreach(var u in Units)u.Children=u.Children.OrderBy(x=>x.Members.Min(p=>p.Birth==""?"9999":p.Birth)).ThenBy(x=>x.Index).ToList();foreach(var unit in Units.OrderByDescending(x=>x.Rank)){float children=unit.Children.Sum(c=>c.Subtree)+Math.Max(0,unit.Children.Count-1)*64;unit.Subtree=Math.Max(unit.Width,children);}
   float left=106;var roots=Units.Where(u=>u.Parent==null).OrderBy(u=>u.Index).ToList();foreach(var u in roots){Position(u,left);left+=u.Subtree+104;}float maxRight=0;foreach(var unit in Units){float y=244+unit.Rank*(CardHeight+124);float x=unit.X;foreach(var p in unit.Members){Boxes[p.Id]=new RectangleF(x,y,CardWidth,CardHeight);x+=CardWidth+34;maxRight=Math.Max(maxRight,x-34);}}Layers=Units.Max(u=>u.Rank)+1;Size=new SizeF(Math.Max(1040,maxRight+86),244+Layers*(CardHeight+124)+36);}
  void Position(DiagramUnit u,float left){var pending=new Stack<Tuple<DiagramUnit,float>>();pending.Push(Tuple.Create(u,left));while(pending.Count>0){var current=pending.Pop();var unit=current.Item1;float pos=current.Item2;unit.X=pos+(unit.Subtree-unit.Width)/2;float width=unit.Children.Sum(c=>c.Subtree)+Math.Max(0,unit.Children.Count-1)*64;float childLeft=pos+(unit.Subtree-width)/2;foreach(var c in unit.Children){pending.Push(Tuple.Create(c,childLeft));childLeft+=c.Subtree+64;}}}
  bool CreateUnits(List<Person> people,Dictionary<string,string> parent,Func<string,string> root){Units.Clear();var map=new Dictionary<string,DiagramUnit>();foreach(var p in people){string id=root(p.Id);DiagramUnit u;if(!map.TryGetValue(id,out u)){u=new DiagramUnit{Index=Units.Count};map[id]=u;Units.Add(u);}u.Members.Add(p);}var unitOf=people.ToDictionary(p=>p.Id,p=>map[root(p.Id)]);var edges=Units.ToDictionary(u=>u,u=>new HashSet<DiagramUnit>());var degrees=Units.ToDictionary(u=>u,u=>0);foreach(var p in people)foreach(string id in new[]{p.FatherId,p.MotherId}){if(!unitOf.ContainsKey(id))continue;var a=unitOf[id];var b=unitOf[p.Id];if(a==b)return false;if(edges[a].Add(b))degrees[b]++;}var queue=new Queue<DiagramUnit>(Units.Where(u=>degrees[u]==0));int count=0;while(queue.Count>0){var u=queue.Dequeue();count++;foreach(var c in edges[u]){c.Rank=Math.Max(c.Rank,u.Rank+1);if(--degrees[c]==0)queue.Enqueue(c);}}return count==Units.Count;}
  public void Draw(DiagramCanvas c,DiagramOptions o,string selected,HashSet<string> collapsed,bool transparent=false){var p=Palette.Get(o.Theme);if(!transparent)c.Rect(0,0,Size.Width,Size.Height,p.Background);float right=Size.Width-62;c.Brand(38,36,48);c.Text("JINGPU   /   FAMILY LINEAGE",104,39,11,p.Gold,true);c.Text(Store.Data.Title,102,62,34,p.Ink,true,Size.Width-180);c.Text(Store.Data.Motto,104,110,12,p.Muted,false,Size.Width-170);c.Segment(48,153,right,153,p.Border,1);c.Text(People.Count+" 位成员     /     "+Layers+" 个谱系层级     /     "+(o.Compact?"紧凑视图":"详细视图"),50,172,13,p.Ink,true);c.Segment(right-282,181,right-250,181,p.Line,2);c.Text("亲子",right-240,173,12,p.Muted);c.Segment(right-177,181,right-145,181,p.Gold,1.7f,true);c.Text("配偶",right-135,173,12,p.Muted);c.Text("景·谱 1.5",right-63,173,11,p.Muted);if(People.Count==0){c.Text("还没有成员",80,300,28,p.Ink,true);c.Text("添加家族成员，建立父母与配偶关系后，这里会自动生成世系图。",80,350,15,p.Muted);Footer(c,p);return;}
   if(o.ShowBands)for(int rank=0;rank<Layers;rank++){float y=244+rank*(CardHeight+124);if(rank%2==0)c.Rect(32,y-24,Size.Width-64,CardHeight+48,p.Soft,18);c.Text((rank+1).ToString("00"),48,y+18,23,p.Gold,true);c.Text("谱系层",46,y+52,10,p.Muted);}
   var familyLanes=new Dictionary<int,int>();foreach(var group in People.GroupBy(x=>x.FatherId+"|"+x.MotherId)){var first=group.First();var parents=new[]{first.FatherId,first.MotherId}.Where(id=>Boxes.ContainsKey(id)).Distinct().ToArray();if(parents.Length==0)continue;var children=group.Where(x=>Boxes.ContainsKey(x.Id)).ToArray();var parentRects=parents.Select(id=>Boxes[id]).ToArray();float childTop=children.Min(x=>Boxes[x.Id].Top);int lane;familyLanes.TryGetValue((int)childTop,out lane);familyLanes[(int)childTop]=lane+1;lane=lane%5;float join=parentRects.Average(r=>r.X+r.Width/2),bus=parentRects.Max(r=>r.Bottom)+27+lane*7,rail=childTop-32-lane*9;foreach(var r in parentRects)c.Line(new[]{new PointF(r.X+r.Width/2,r.Bottom),new PointF(r.X+r.Width/2,bus),new PointF(join,bus)},p.Line,1.8f);c.Circle(join,bus,3.5f,p.Line);c.Line(new[]{new PointF(join,bus),new PointF(join,rail)},p.Line,1.8f);float min=Math.Min(join,children.Min(x=>Boxes[x.Id].X+CardWidth/2)),max=Math.Max(join,children.Max(x=>Boxes[x.Id].X+CardWidth/2));c.Segment(min,rail,max,rail,p.Line,1.8f);foreach(var child in children){var r=Boxes[child.Id];c.Segment(r.X+r.Width/2,rail,r.X+r.Width/2,r.Top,p.Line,1.8f);}}
   foreach(var person in People)foreach(string id in person.Spouses){if(String.CompareOrdinal(person.Id,id)>=0||!Boxes.ContainsKey(id))continue;var a=Boxes[person.Id];var b=Boxes[id];var l=a.X<b.X?a:b;var r=a.X<b.X?b:a;if(Math.Abs(a.Y-b.Y)<1&&r.X-l.Right<50){float y=a.Y+36;c.Segment(l.Right,y,r.X,y,p.Gold,1.5f,true);c.Circle((l.Right+r.X)/2-3,y,3.6f,p.Background,p.Gold);c.Circle((l.Right+r.X)/2+3,y,3.6f,p.Background,p.Gold);}else{float y=Math.Min(a.Y,b.Y)-15;c.Line(new[]{new PointF(a.X+a.Width/2,a.Y),new PointF(a.X+a.Width/2,y),new PointF(b.X+b.Width/2,y),new PointF(b.X+b.Width/2,b.Y)},p.Gold,1.4f,true);}}
   int photo=0;foreach(var person in People){c.BeginMember(person.Id,person.Name,person.Name+" | "+Life(person)+" | "+person.Place+" | "+person.Occupation);var r=Boxes[person.Id];bool active=person.Id==selected;string accent=person.Gender=="女"?p.Female:(o.Theme==1?p.Muted:p.Line);c.Rect(r.X+1,r.Y+4,r.Width,r.Height,o.Theme==1?"#0c1e20":"#e6e7de",16);c.Rect(r.X,r.Y,r.Width,r.Height,p.Card,16,active?p.Gold:p.Border,active?2.3f:1);c.Rect(r.X+16,r.Y+19,3,35,accent,1.5f);bool image=o.ShowPhotos&&person.Portrait!=""&&c.Photo(Path.Combine(Store.Root,person.Portrait),r.X+28,r.Y+18,40,(photo++).ToString());if(!image){c.Circle(r.X+48,r.Y+38,20,o.Theme==1?"#284748":"#edf0e7");c.Text(person.Name.Length>0?person.Name.Substring(0,1):"?",r.X+38,r.Y+24,20,p.Ink,true);}c.Text(person.Name,r.X+80,r.Y+20,20,p.Ink,true,r.Width-131);c.Rect(r.Right-44,r.Y+24,28,23,o.Theme==1?"#284748":"#f0f1e9",7);c.Text(person.Gender=="未知"?"?":person.Gender,r.Right-37,r.Y+27,12,accent,true);string second=(o.ShowGeneration&&person.Generation!=""?person.Generation+" 字辈":"")+(o.ShowJob&&person.Occupation!=""?"  ·  "+person.Occupation:"");c.Text(second.Trim(' ','·'),r.X+80,r.Y+46,11,p.Muted,false,r.Width-98);c.Segment(r.X+20,r.Y+76,r.Right-20,r.Y+76,p.Border,1);
    if(o.Compact){string line=o.ShowDates?Life(person):o.ShowPlace?person.Place:"";c.Text(line,r.X+20,r.Y+85,11,p.Muted,false,r.Width-40);}else{if(o.ShowDates)c.Text(Life(person),r.X+20,r.Y+88,12,p.Ink,false,r.Width-40);if(o.ShowPlace)c.Text("籍贯  "+(person.Place==""?"尚未记录":person.Place),r.X+20,r.Y+115,12,p.Muted,false,r.Width-40);string note=collapsed.Contains(person.Id)?"＋ 分支已收起":"子女 "+Store.Data.People.Count(x=>x.FatherId==person.Id||x.MotherId==person.Id)+"  ·  资料 "+Store.Data.Documents.Count(x=>x.PersonId==person.Id)+"  ·  "+(person.Death==""?(person.Biography!=""?"已录生平":"生平待录"):Age(person));c.Text(note,r.X+20,r.Y+146,10,p.Muted,false,r.Width-40);}if(o.Compact&&collapsed.Contains(person.Id))c.Circle(r.Right-14,r.Bottom-14,5,p.Gold);c.EndMember();
   }Footer(c,p);
  }
  string Age(Person p){if(p.Birth==""||p.Death=="")return "已录生卒";int age=Store.DateStart(p.Death).Year-Store.DateStart(p.Birth).Year;if(p.Birth.Length==10&&p.Death.Length==10){var b=Store.DateStart(p.Birth);var d=Store.DateStart(p.Death);if(d.Month<b.Month||(d.Month==b.Month&&d.Day<b.Day))age--;return "享年 "+Math.Max(0,age)+" 岁";}return "享年约 "+Math.Max(0,age)+" 岁";}
  string Life(Person p){return (p.Birth==""?"生年未录":p.Birth.Replace('-','.'))+"  —  "+(p.Death==""?"未录":p.Death.Replace('-','.'));}
  void Footer(DiagramCanvas c,Palette p){float y=Size.Height-62;c.Segment(48,y,Size.Width-48,y,p.Border,1);c.Text("记录亲缘  ·  传承家风",48,y+18,11,p.Muted);c.Text(Notice==""?"谱系层级为当前视图的相对层级；关系以档案记录为准。":Notice,Size.Width-510,y+18,10,p.Muted,false,460);}
 }
